import java.sql.*; import java.util.*;
public class IssueDAO { public static final int BORROWING_LIMIT=5;
 public boolean issueBook(int b,int m)throws SQLException{return transact(b,m,false);} public boolean returnBook(int issue)throws SQLException{try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try(PreparedStatement p=c.prepareStatement("SELECT book_id FROM issues WHERE issue_id=? AND status='ISSUED' FOR UPDATE")){p.setInt(1,issue);try(ResultSet r=p.executeQuery()){if(!r.next())throw new SQLException("Issue not found or already returned.");int b=r.getInt(1);try(PreparedStatement a=c.prepareStatement("UPDATE issues SET status='RETURNED',return_date=CURDATE() WHERE issue_id=?");PreparedStatement d=c.prepareStatement("UPDATE books SET available_copies=available_copies+1 WHERE book_id=? AND available_copies<total_copies")){a.setInt(1,issue);a.executeUpdate();d.setInt(1,b);if(d.executeUpdate()!=1)throw new SQLException("Copy count is inconsistent.");c.commit();return true;}}}catch(Exception e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}}
 private boolean transact(int b,int m,boolean z)throws SQLException{try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try{try(PreparedStatement p=c.prepareStatement("SELECT available_copies FROM books WHERE book_id=? FOR UPDATE")){p.setInt(1,b);try(ResultSet r=p.executeQuery()){if(!r.next()||r.getInt(1)<1)throw new SQLException("Book unavailable.");}}try(PreparedStatement p=c.prepareStatement("SELECT COUNT(*) FROM issues WHERE member_id=? AND status='ISSUED'")){p.setInt(1,m);try(ResultSet r=p.executeQuery()){r.next();if(r.getInt(1)>=BORROWING_LIMIT)throw new SQLException("Borrowing limit reached.");}}try(PreparedStatement p=c.prepareStatement("INSERT INTO issues(book_id,member_id,issue_date,due_date,status) VALUES(?,?,CURDATE(),DATE_ADD(CURDATE(),INTERVAL 14 DAY),'ISSUED')")){p.setInt(1,b);p.setInt(2,m);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("UPDATE books SET available_copies=available_copies-1 WHERE book_id=?")){p.setInt(1,b);p.executeUpdate();}c.commit();return true;}catch(Exception e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}}
 public List<Issue> getAllIssues()throws SQLException{return list("");} public List<Issue> getCurrentIssues()throws SQLException{return list("WHERE status='ISSUED'");} public List<Issue> getOverdueIssues()throws SQLException{return list("WHERE status='ISSUED' AND due_date<CURDATE()");} private List<Issue> list(String w)throws SQLException{List<Issue>x=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM issues "+w);ResultSet r=p.executeQuery()){while(r.next())x.add(new Issue(r.getInt("issue_id"),r.getInt("book_id"),r.getInt("member_id"),r.getDate("issue_date"),r.getDate("due_date"),r.getDate("return_date"),r.getString("status")));}return x;}}
